(() => {
 const data=window.v2Exhibits, regionSamples=(window.v2Regions||[]).map(p=>({provinceId:p.id,region:p.name,color:p.color,number:p.index,theme:new Set(data.filter(d=>d.provinceId===p.id).map(d=>d.brand)).size+' 个品牌',count:data.filter(d=>d.provinceId===p.id).length})), direction=document.documentElement.dataset.direction;
 const params=new URLSearchParams(location.search),view=params.get('view')||'home';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const asset=p=>p.startsWith('v2:')?p.slice(3):''+p;
 const url=(v,id)=>'?view='+v+(id?'&item='+encodeURIComponent(id):'');
 let saved;try{saved=new Set(JSON.parse(localStorage.getItem('smoke-v2-saved')||'[]').filter(id=>data.some(d=>d.id===id)));}catch{saved=new Set();}
 let selected=params.get('region')||'shanghai';
 const seed=data.find(d=>d.id===params.get('item'))||data[0];
 const label=s=>`<p class="eyebrow">${s}</p>`;
 const photo=(d,cls='')=>`<img class="${cls}" src="${asset(d.packFront)}" alt="${esc(d.name)}包装参考正面" loading="lazy" decoding="async">`;
 const badge='<span class="reference">参考图 · 许可待确认</span>';
 function packageCard(d){return `<article class="label-card" style="--accent:${d.color}"><button class="card-save" data-save="${d.id}" aria-label="收藏${esc(d.name)}" aria-pressed="${saved.has(d.id)}">♡</button><a class="label-image" href="${url('detail',d.id)}" aria-label="查看${esc(d.name)}烟标档案">${photo(d)}<span class="catalog-no">SA / ${d.number}</span></a><div class="label-caption"><p>${esc(d.region)} · ${esc(d.theme)}</p><h3><a href="${url('detail',d.id)}">${esc(d.name)}</a></h3><span>${esc(d.observations[0])}</span>${badge}</div></article>`;}
 const mapDocument=new DOMParser().parseFromString(chinaMapSvg,'image/svg+xml');
 function regionCard(d){const shape=mapDocument.querySelector('[data-province="'+d.provinceId+'"]');return `<a class="region-card" href="?view=regions&region=${d.provinceId}" aria-label="进入${esc(d.region)}"><svg class="region-terrain" aria-hidden="true" focusable="false" preserveAspectRatio="xMidYMid meet">${shape?.outerHTML||''}</svg><h3>${esc(d.region)}</h3></a>`;}
 function characterCard(d){return `<article class="character-card" style="--accent:${d.color}"><button class="reveal" data-reveal="${d.id}" aria-label="揭示${esc(d.name)}角色" aria-pressed="false"><span>CHARACTER STUDY / ${d.number}</span><img src="${asset(d.preview)}" alt="${esc(d.name)}的原创角色剪影" loading="lazy" class="silhouette"><span class="reveal-hint">点按揭示轮廓 ＋</span></button><div><h3>${esc(d.title)}</h3><p>${d.translations[0][0]} → ${d.translations[0][1]}</p><a href="${url('detail',d.id)}#character">查看转译</a><button class="text-button" data-image="${asset(d.portrait)}" data-title="${esc(d.name)} · ${d.artVersion==='v2'?'原创立绘':'原有立绘'}">直接查看立绘 ↗</button><small>${d.artVersion==='v2'?'原创立绘':'原有立绘'} · ${d.type}</small></div></article>`;}
 function mapOverview(){return `<section class="atlas-heading"><h1>方寸之间，<em>另有天地。</em></h1></section><section class="atlas-map" aria-label="选择省份"><div id="region-map">${chinaMapSvg}</div></section><section class="atlas-provinces" id="provinces" aria-label="省份入口"><div class="region-grid">${regionSamples.map(regionCard).join('')}</div></section>`;}
 function home(){return mapOverview();}
 function regions(){if(!params.get('region'))return mapOverview();return `<div class="detail-breadcrumb"><a href="?view=home">地图首页</a><span>/</span><span>省份展厅</span></div><div id="region-detail" class="province-room" aria-live="polite"></div>`;}
 function duetCard(d){return `<article class="duet-card"><button class="card-save" data-save="${d.id}" aria-label="收藏${esc(d.name)}" aria-pressed="${saved.has(d.id)}">♡</button><div class="duet-scene"><button class="duet-character reveal" data-reveal="${d.id}" aria-label="揭示${esc(d.name)}人物" aria-pressed="false"><img src="${asset(d.preview)}" alt="${esc(d.name)}角色剪影" class="silhouette" loading="lazy"><span class="reveal-hint">点按揭示</span></button><a class="duet-pack" href="${url('detail',d.id)}" aria-label="查看${esc(d.name)}档案">${photo(d)}</a></div><div class="duet-caption"><h3><a href="${url('detail',d.id)}">${esc(d.name)}</a></h3><button class="duet-view" data-image="${asset(d.portrait)}" data-title="${esc(d.name)} · 立绘">看立绘 ↗</button></div></article>`;}
 function regionDetail(){const rows=data.filter(d=>d.provinceId===selected),region=regionSamples.find(p=>p.provinceId===selected),target=document.querySelector('#region-detail');if(!target)return;target.innerHTML=`<div class="region-intro"><h1>${esc(region?.region||'地域')}</h1></div>`+(rows.length?`<section class="duet-grid" aria-label="人物与烟标">${rows.map(duetCard).join('')}</section>`:'<div class="empty"><p>这里的档案还在整理。</p><a class="button" href="?view=home">看看其他省份</a></div>');}
 function labels(){return `<section class="page-heading">${label('让包装成为观看的中心','LABEL INDEX')}<h1>方寸之间的<em>颜色与秩序。</em></h1><p>从参考包装，阅读不同构图。清晰度与转载许可尚未认证，保留原照可见边界。</p></section><div class="filter-bar"><label>筛选主题 <select id="theme-filter"><option value="">全部主题</option>${[...new Set(data.map(d=>d.theme))].map(t=>`<option>${t}</option>`).join('')}</select></label><span id="filter-count">${data.length} 件展品 / 非销量排名</span><button id="density" aria-pressed="false">切换密集陈列</button></div><section class="label-grid index-grid" id="label-index">${data.map(packageCard).join('')}</section>`;}
 function characters(){return `<section class="page-heading">${label('先认轮廓，再看人物','CHARACTER STUDIES')}<h1>想象，有自己的<em>轮廓。</em></h1><p>点按剪影揭示角色。角色图像版本会逐件标明；下方展签说明包装线索如何进入原创方向。</p></section><section class="character-grid">${data.map(characterCard).join('')}</section>`;}
 function detail(){return `<div class="detail-breadcrumb"><a href="?view=home">地图首页</a><span>/</span><a href="?view=regions&region=${seed.provinceId}">${seed.region}</a><span>/ ${seed.name}</span></div><section class="exhibit-top"><div class="object-stage"><span class="object-number">SA / ${seed.number}</span>${photo(seed)}${badge}<button class="button" data-image="${asset(seed.packFront)}" data-title="${esc(seed.name)} · 原始参考图">查看包装正面 ＋</button></div><div class="exhibit-intro">${label('一件展品的六层叙事','EXHIBIT / '+seed.number)}<h1>${seed.title}</h1><p class="exhibit-name">${seed.name} <span>${seed.region} · ${seed.theme}</span></p><p class="standfirst">${seed.observations.join('；')}。从这些可见细节开始，阅读另一种想象。</p><div class="layer-links"><a href="#observations">01 看见</a><a href="#reading">02 解读</a><a href="#character">03 转译</a><a href="#fiction">04 故事</a></div><button class="button" data-save="${seed.id}" aria-pressed="${saved.has(seed.id)}">${saved.has(seed.id)?'已收入收藏':'收入本地收藏'} ♡</button><p class="micro">包装版本未认证 · 地域为品牌关联 · 角色非官方原创</p></div></section><div class="narrative"><section class="narrative-section" id="observations"><div>${label('事实 / 目视观察','01 / OBSERVE')}<h2>先看见什么。</h2></div><div><ol class="observations">${seed.observations.map(s=>`<li>${s}</li>`).join('')}</ol><p class="evidence">依据：本地参考照片人工目视，2026-10-15。小图无法辨认的文字和建筑细节不补写。</p>${seed.sourceReferences.map(s=>`<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><p class="micro">原资料访问日期 ${s.accessed}；本轮未新增线上交叉核验。</p>`).join('')}</div></section><section class="narrative-section" id="reading"><div>${label('解读 / 策展视角','02 / INTERPRET')}<h2>形状怎样<br>成为意味。</h2></div><div><p class="reading-text">${seed.reading}</p><p class="evidence">策展解读，不代表品牌官方设计释义。品牌历史与具体年代待进一步核实。</p></div></section><section class="narrative-section" id="character"><div>${label('创作 / 形象转译','03 / TRANSLATE')}<h2>把符号，<br>交给想象。</h2><p>${seed.type}${seed.alternative?'<br>备选方向：'+seed.alternative:''}</p></div><div><div class="translation-list">${seed.translations.map((t,i)=>`<article><span>0${i+1}</span><p>${t[0]}</p><b>↘</b><h3>${t[1]}</h3></article>`).join('')}</div><button class="character-preview" data-image="${asset(seed.portrait)}" data-title="${seed.name} · ${seed.artVersion==='v2'?'原创立绘':'原有立绘'}"><img src="${asset(seed.preview)}" alt="${seed.name}的原创角色" loading="lazy"><span>查看完整立绘 ＋<small>${seed.artVersion==='v2'?'原创形象 · 已保留当前版本':'原有立绘 · 保留原作'}</small></span></button></div></section><section class="narrative-section fiction" id="fiction"><div>${label('虚构 / 非官方原创短篇','04 / FICTION')}<h2>${seed.title}</h2></div><div><p>${seed.lore}</p><span class="fiction-stamp">原创虚构 · 与品牌历史无关</span></div></section><section class="narrative-section"><div>${label('来源边界','05 / NOTES')}<h2>记忆，也需要<br>保留空白。</h2></div><div><p>本件尚未收录可核实的民间俗语。暂不沿用缺少流传证据的段子，也不把产品别称自动当成地方史。</p><details><summary>关于图像、角色与资料的声明</summary><p>包装为原有资料参考图；清晰度和转载许可待确认，不能据此宣称高清或授权完成。原型仅用于内部视觉评审。角色和短篇为非官方原创；v2样板与v1参考分别保留，不代表官方形象。吸烟有害健康。</p></details></div></section></div><section class="selection-section"><div class="section-title">${label('继续漫游','06 / RELATED')}<h2>下一件，换个角度。</h2></div><div class="label-grid">${seed.relatedIds.map(id=>packageCard(data.find(d=>d.id===id))).join('')}</div></section>`;}
 function themes(){return `<section class="page-heading">${label('策展专题 / 概念预览','EXHIBITIONS')}<h1>把作品，放回<em>彼此之间。</em></h1><p>围绕可见图案建立联系，沿着两组策展线索，比较图形怎样改变观看顺序。</p></section>${['建筑的回声','印刷的秩序'].map(t=>`<section class="selection-section"><h2>${t}</h2><p>${t==='建筑的回声'?'屋檐、层楼与横向的安定感。':'方印、横带与边框，图形怎样安排我们的视线。'}</p><div class="label-grid">${data.filter(d=>d.theme===t).map(packageCard).join('')}</div></section>`).join('')}`;}
 function collection(){return `<section class="page-heading">${label('仅保存在当前浏览器','YOUR COLLECTION')}<h1>把看见的，<em>留下来。</em></h1><p>收藏保存在当前浏览器中。</p></section><section class="label-grid">${data.filter(d=>saved.has(d.id)).map(packageCard).join('')||'<div class="empty"><p>这里还没有展品。</p><a class="button" href="?view=labels">去烟标索引看看 ↗</a></div>'}</section>`;}
 function votes(){return `<section class="page-heading">${label('G7 前不开放公众投票','VISITOR’S CHOICE')}<h1>你记住的，<em>是哪一种设计？</em></h1><p>这里将记录烟标图案与文化主题的审美偏好，不评选口感、销量或购买价值。</p></section><section class="empty vote-preview"><h2>计票尚未开放</h2><p>今日 / 七日 / 累计。正式实现需服务端每日一票、北京时间日界线、异常票撤回与口径公示，并经过 G7 审查。本阶段没有虚构票数。</p><a class="button" href="?view=labels">先看设计档案 ↗</a></section>`;}
 function about(){return `<section class="page-heading"><p class="eyebrow">ABOUT THE ARCHIVE</p><h1>方寸纸面，<em>无限想象。</em></h1><p>一个从包装设计出发，连接地域、图形与原创角色的非官方视觉文化档案。</p></section><section class="about-content"><h2>从看见，到想象。</h2><p>地图是入口。选择一个地方，观察一张包装上的线条、颜色与图案，再读它怎样进入另一种原创形象。档案中的资料、策展解读和虚构故事分开标注。</p><h2>保留图像，也保留空白。</h2><p>本期收录126份档案，关联31个地区。已完成的34张新立绘保留，其他92件沿用原有立绘。创作版本分别记录；包装仍为参考图，清晰度与转载许可尚未确认。</p><h2 id="sources">关于资料与表达。</h2><p><a href="https://www.geoboundaries.org/" target="_blank" rel="noopener noreferrer">地图轮廓来源：geoBoundaries</a></p><p>品牌名称和包装用于视觉文化讨论，角色与故事为非官方原创。本馆不评价口感、购买价值或销量；不提供购买入口。吸烟有害健康。</p><p><a class="button" href="?view=home">回到地图，开始观看 ↗</a></p></section>`;}
 const screens={home,regions,labels,characters,detail,themes,collection,votes,about};
 document.querySelector('#app').innerHTML=`<header class="site-header"><a class="brand" href="?view=home"><span class="brand-seal">档</span><span>烟标档案</span></a><nav aria-label="主导航">${[['labels','烟标']].map(([v,n])=>`<a href="?view=${v}" ${(view===v||(v==='home'&&view==='regions'))?'aria-current="page"':''}>${n}</a>`).join('')}</nav></header><main id="main">${(screens[view]||home)()}</main><footer><p>非官方原创 · 吸烟有害健康</p><div><a href="?view=collection">收藏</a><a href="?view=about">关于</a></div></footer><dialog id="image-view" aria-labelledby="image-title"><div class="image-toolbar"><h2 id="image-title">参考图细看</h2><button id="image-zoom" aria-pressed="false">放大 2×</button><button id="image-close" aria-label="关闭图片">×</button></div><div class="image-stage"><img alt=""></div><p>原始资料尺寸展示 · 放大不代表高清 · 放大后滑动查看</p></dialog>`;
 document.querySelectorAll('.region-terrain').forEach(svg=>{const shape=svg.querySelector('[data-province]');if(!shape)return;const b=shape.getBBox();svg.setAttribute('viewBox',`${b.x-2} ${b.y-2} ${b.width+4} ${b.height+4}`);shape.setAttribute('tabindex','-1');shape.removeAttribute('role');});
 const liveMap=document.querySelector('#region-map svg');if(liveMap){liveMap.setAttribute('role','group');liveMap.querySelector('.map-points')?.remove();for(const d of regionSamples)if(d.count)liveMap.querySelector('path[data-province="'+d.provinceId+'"]')?.classList.add('has-exhibits');}
 if(view==='regions')regionDetail();if(view==='home'||view==='regions'){document.querySelectorAll('#region-map [data-province]').forEach(p=>{p.setAttribute('tabindex','0');p.setAttribute('role','button');p.setAttribute('aria-label','选择'+(regionSamples.find(d=>d.provinceId===p.dataset.province)?.region||'地域展厅'));});}
 document.addEventListener('click',e=>{const region=e.target.closest('[data-region],#region-map [data-province]');if(region){selected=region.dataset.region||region.dataset.province;location.href='?view=regions&region='+encodeURIComponent(selected);return;}const reveal=e.target.closest('[data-reveal]');if(reveal){if(reveal.getAttribute('aria-pressed')==='true'){location.href=url('detail',reveal.dataset.reveal);return;}reveal.setAttribute('aria-pressed','true');const img=reveal.querySelector('img');img.classList.remove('silhouette');img.alt=img.alt.replace('角色剪影','参考角色');reveal.querySelector('.reveal-hint').textContent='再点进入档案';return;}const save=e.target.closest('[data-save]');if(save){saved.has(save.dataset.save)?saved.delete(save.dataset.save):saved.add(save.dataset.save);try{localStorage.setItem('smoke-v2-saved',JSON.stringify([...saved]));}catch{}document.querySelectorAll('[data-save]').forEach(b=>{if(b.dataset.save===save.dataset.save)b.setAttribute('aria-pressed',String(saved.has(save.dataset.save)));});save.dispatchEvent(new CustomEvent('archive-save-change',{bubbles:true}));}const image=e.target.closest('[data-image]');if(image){const dialog=document.querySelector('#image-view');document.querySelector('#image-title').textContent=image.dataset.title;dialog.querySelector('img').src=image.dataset.image;dialog.querySelector('img').alt=image.dataset.title;dialog.querySelector('.image-stage').classList.remove('zoomed');document.querySelector('#image-zoom').setAttribute('aria-pressed','false');document.querySelector('#image-zoom').textContent='放大 2×';dialog.showModal();document.body.classList.add('modal-open');}});
 document.querySelector('#image-close').onclick=()=>document.querySelector('#image-view').close();
 document.querySelector('#image-zoom').onclick=e=>{const stage=document.querySelector('.image-stage'),on=stage.classList.toggle('zoomed');e.target.setAttribute('aria-pressed',String(on));e.target.textContent=on?'适应屏幕':'放大 2×';requestAnimationFrame(()=>{stage.scrollLeft=on?(stage.scrollWidth-stage.clientWidth)/2:0;stage.scrollTop=on?(stage.scrollHeight-stage.clientHeight)/2:0;});};
 document.querySelector('#image-view').addEventListener('close',()=>document.body.classList.remove('modal-open'));
 document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('#region-map [data-province]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
 document.querySelector('#density')?.addEventListener('click',e=>{const on=document.querySelector('#label-index').classList.toggle('dense');e.target.setAttribute('aria-pressed',String(on));});
})();
